        return 1
    if (s[0], s[1]) == (x, y) or (s[0], s[1]) == (x+1, y) or (s[0], s[1]) == (x-1, y) or (s[0], s[1]) == (x, y+1) or (s[0], s[1]) == (x, y-1):
        return 2
    if s[0] == x and s[1] == y:
        return 1
    if s[0] == x and s[1] < y:
        return shortest_path((s[0], s[1]+1), (x, y), x, y+1)
    if s[0] == x and s[1] > y:
        return shortest_path((s[0], s[1]-1), (x, y), x, y-1)
    if s[1] == y and s[0] == x:
        return 1
    if s[1] == y and s[0] < x:
        return shortest_path((s[0]+1, s[1]), (x, y), x+1, y)
    if s[1] == y and s[0] > x:
        return shortest_path((s[0]-1, s[1]), (x, y), x-1, y)
    return 0

