def paths_with_obstacles(grid: list[list[int]]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0)]  # right, down

    def is_safe(row, col):
        return 0 <= row < rows and 0 <= col < cols and grid[row][col] == 0

    def is_end(row, col):
        return row == rows - 1 and col == cols - 1

    def dfs(row, col):
        if row == rows - 1 and col == cols - 1:
            return 1
        count = 0
        for dr, dc in directions:
            nr, nc = row + dr, col + dc
            if is_safe(nr, nc):
                count += dfs(nr, nc)
        return count

    if grid[0][0] == 1 or grid[rows-1][cols-1] == 1:
        return 0
    return dfs(0, 0)
