def caesar_shift(s: str, k: int) -> str:
    result = ""
    for char in s:
        if char.isalpha():
            ascii_offset = 97 if char.islower() else 65
            result += chr((ord(char) - ascii_offset + k) % 26 + ascii_offset)
        else:
            result += char
    return result
