def group_anagrams(words: list[str]) -> list[list[str]]:
    anagrams = {}
    for word in words:
        key = tuple(sorted(word))
        if key in anagrams:
            anagrams[key].append(word)
        else:
            anagrams[key] = [word]

    result = []
    for key, value in anagrams.items():
        result.append(sorted(value))

    for key in anagrams:
        result.append(key)

    result.sort()
    return result
